&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9hnel&quot; data-offset-key=&quot;9dqb2-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;9dqb2-0-0&quot;&gt;&lt;span data-offset-key=&quot;9dqb2-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Is the expert on target personas and segments, how customers buy and users adopt our products, and the value they derive from them&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
